<script>
    function calcRowTotals() {
        // หาทุกแถวในตาราง (ยกเว้น header)
        const rows = document.querySelectorAll("".tbgreen tr"");

        rows.forEach(row => {
            const manInputs = row.querySelectorAll("".input-man"");
            const autoInputs = row.querySelectorAll("".input-auto"");
            const totalInput = row.querySelector("".input-total"");
            //const remainInput = row.querySelector("".input-remain"");


            if (totalInput) {
                // ฟังก์ชันคำนวณรวมในแถว
                const updateTotal = () => {
                    let sum = 0;
                    [...manInputs, ...autoInputs].forEach(inp => {
                        let val = parseFloat(inp.value) || 0;
                        sum += val;
                    });
                    totalInput.value = sum.toFixed(2);
                    // remainInput.value = sum;
                };

                // ผูก event ให้คำนวณใหม่เมื่อกรอกค่า
        ");
            WriteLiteral(@"        [...manInputs, ...autoInputs].forEach(input => {
                    input.addEventListener(""input"", updateTotal);
                });

                // คำนวณครั้งแรกตอนโหลดหน้า
                updateTotal();
            }
        });
    }

    // เรียกฟังก์ชันตอนโหลดหน้า
    document.addEventListener(""DOMContentLoaded"", calcRowTotals);

    $(document).ready(function () {
        $(document).on('paste', '.input-man, .input-auto', function (e) {

            var clipboardData = e.originalEvent.clipboardData || window.clipboardData;
            var pastedData = clipboardData.getData('text');

            if (!pastedData || !pastedData.includes('\t')) {
                return;
            }

            e.preventDefault();

            var cleanData = pastedData.replace(/\r?\n|\r/g, '');
            var columns = cleanData.split('\t');

            var $currentInput = $(this);
            var $currentTable = $currentInput.closest('table');

            // ค้นหาช่องที่เป");
            WriteLiteral(@"ิดให้กรอกจริงในตารางนี้
            var $editableInputs = $currentTable.find('.input-man, .input-auto').filter(function () {
                var $this = $(this);
                var isParentHidden = $this.closest('td').css('display') === 'none';
                var isReadonly = $this.prop('readonly') || $this.attr('readonly') === 'readonly';

                return !isParentHidden && !isReadonly;
            });

            var startInputIndex = $editableInputs.index($currentInput);

            // วนลูปวางข้อมูล
            columns.forEach(function (value, index) {
                var targetIndex = startInputIndex + index;

                if (targetIndex < $editableInputs.length) {
                    var $targetInput = $editableInputs.eq(targetIndex);

                    // 🔥 ลบเครื่องหมายคอมมา (,) ออกจากตัวเลขก่อนนำไปใส่ในช่อง
                    var cleanValue = value.trim().replace(/,/g, '');

                    $targetInput.val(cleanValue);

                    $targetInput.t");
            WriteLiteral(@"rigger('change');
                    $targetInput.trigger('input');
                }
            });

            // เรียกใช้ฟังก์ชันคำนวณยอดรวมทันทีหลังจากวางข้อมูลเสร็จทุกช่อง
            if (typeof calcRowTotals === ""function"") {
                calcRowTotals();
            }

        });
    });
</script>
